    # the grid into the most balanced pair of panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and 0 < r < h - 1:
            separators.append((min(r, h - r - 1), "row", r))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)) and 0 < c < w - 1:
            separators.append((min(c, w - c - 1), "col", c))

    _, direction, s = max(separators)

    if direction == "row":
        n = min(s, h - s - 1)
        top = grid[:n]
        bottom = grid[s + 1:s + 1 + n]

        def mode(rows):
            counts = {}
            for row in rows:
                for v in row:
