        if all(grid[r][c] == grid[0][c] for r in range(h)):
            dividers.append(("col", c))

    direction, s = dividers[0]

    def mode(values):
        counts = {}
        for v in values:
            counts[v] = counts.get(v, 0) + 1
        return max(counts, key=counts.get)

    if direction == "col":
        n = min(s, w - s - 1)
